    components = []
    for i in range(rows):
        for j in range(cols):
            if not visited[i, j] and grid[i, j] != 0:
                comp = []
                queue = deque([(i, j)])
                visited[i, j] = True
                while queue:
                    r, c = queue.popleft()
                    comp.append((r, c))
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
