                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr, nc] and grid[nr, nc] != 0:
                                visited[nr, nc] = True
                                queue.append((nr, nc))
                components.append(comp)
    return components

components = find_all_components(grid)

