import numpy as np
from collections import deque

# Reparse task input
lines = task_input.strip().split('\n')
rows, cols = len(lines), len(lines[0].strip().split())
grid = np.array([[int(c) for c in line.split()] for line in lines], dtype=int)
special_cells = [(2, 10, 4), (14, 16, 8), (21, 27, 6)]

print("Grid values around special cells:")
for sr, sc, sval in special_cells:
    print(f"  ({sr},{sc})={sval}:")
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            r, c = sr + dr, sc + dc
            val = "*" if not (0 <= r < rows and 0 <= c < cols) else grid[r,c]
            marker = " <-- SPECIAL" if (r==sr and c==sc) else ""
            print(f"    ({r},{c})={val}{marker}")

def find_1_components(grid):
    """Find connected components of 1-cells only"""
    visited = np.zeros_like(grid, dtype=bool)
    components = []

    for i in range(rows):
        for j in range(cols):
            if visited[i,j] or grid[i,j] != 1:
                continue
            comp = []
            queue = deque([(i, j)])
            visited[i, j] = True
            while queue:
                r, c = queue.popleft()
                comp.append((r, c))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if not visited[nr, nc] and grid[nr, nc] == 1:
                            visited[nr, nc] = True
                            queue.append((nr, nc))
            components.append(comp)

    return components

ones_comps = find_1_components(grid)
print(f"\nFound {len(ones_comps)} connected components of 1-cells")

# Now determine which ones are "enclosed" - cannot reach background 0 through 1-path
output_grid = grid.copy()

def is_enclosed(comp_positions, grid):
    """Check if component is fully enclosed (no path to background through itself)"""
    # For each cell in component, try to trace to background
    # If ANY cell can reach background, component is NOT enclosed

    for r, c in comp_positions:
        # BFS to see if we can reach any background cell
        bg_reachable = False
        visited = set()
        queue = deque([(r, c)])

        while queue:
            curr_r, curr_c = queue.popleft()
            if (curr_r, curr_c) in visited:
                continue
            visited.add((curr_r, curr_c))

            # Check neighbors - if neighbor is 0, we reached background!
            for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nr, nc = curr_r + dr, curr_c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr, nc] == 0:
                        bg_reachable = True
                        break
                    elif grid[nr, nc] == 1 and (nr, nc) not in visited:
                        queue.append((nr, nc))

            if bg_reachable:
                break

        if bg_reachable:
            return False  # This component connects to background

    return True  # Fully enclosed

# Fill enclosed components
filled_count = 0
for comp_idx, comp_positions in enumerate(ones_comps):
    is_enclosed_comp = is_enclosed(comp_positions, grid)
    special_val_in_comp = None

    # Check if this component has a special cell nearby
    for r, c in comp_positions:
        for sr, sc, sval in special_cells:
            if abs(r - sr) <= 5 and abs(c - sc) <= 5:  # Nearby?
                special_val_in_comp = sval
                break
        if special_val_in_comp:
            break

    if is_enclosed_comp and special_val_in_comp:
        for r, c in comp_positions:
            output_grid[r, c] = special_val_in_comp
            filled_count += 1
        print(f"Component {comp_idx}: ENCLOSED, filling with value {special_val_in_comp}, {len(comp_positions)} cells")
    elif special_val_in_comp:
        print(f"Component {comp_idx}: NOT enclosed (reaches bg), NOT filling")
    else:
        print(f"Component {comp_idx}: No nearby special cell")

print(f"\nTotal filled cells: {filled_count}")

submission = output_grid.tolist()

