# Sample cell from component 0 that I claimed is enclosed
sr, sc = 2, 9
print(f"Cell ({sr},{sc}) value: {grid[sr, sc]}")

print(f"\nAll neighbors of ({sr},{sc}):")
for dr in [-1, 0, 1]:
    for dc in [-1, 0, 1]:
        if dr == 0 and dc == 0:
            continue
        nr, nc = sr + dr, sc + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            val = grid[nr, nc]
            marker = ""
            if val == 0:
                marker = "<-- BG!"
            print(f"  ({nr},{nc}): {val} {marker}")

# Now trace BFS through 1s
print(f"\nBFS from ({sr},{sc}) through 1s:")
q = deque([(sr, sc)])
visited = {(sr, sc)}
path = [(sr, sc)]

found_bg = False
while q:
    rr, cc = q.popleft()
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        nr, nc = rr + dr, cc + dc
        if 0 <= nr < rows and 0 <= nc < cols:
