                visited.add((nr, nc))
                if grid[nr, nc] == 0:
                    print(f"Found bg at ({nr},{nc})!")
                    found_bg = True
                elif grid[nr, nc] == 1:
                    path.append((nr, nc))
                    q.append((nr, nc))
                break

    if found_bg:
        break

if not found_bg:
    print(f"BFS explored {len(visited)} 1-cells without finding bg")
    print(f"Last few positions: {path[-10:]}")

import numpy as np
from collections import deque

lines = task_input.strip().split('\n')
rows, cols = len(lines), len(lines[0].strip().split())
grid = np.array([[int(c) for c in line.split()] for line in lines], dtype=int)
special_cells = [(2, 10, 4), (14, 16, 8), (21, 27, 6)]

def find_nonzero_components(grid):
    visited = np.zeros_like(grid, dtype=bool)
    components = []
    h_rows, h_cols = grid.shape
    for i in range(h_rows):
        for j in range(h_cols):
            if visited[i,j] or grid[i,j] == 0:
                continue
            comp = []
            q = deque([(i, j)])
            visited[i, j] = True
            while q:
                r, c = q.popleft()
                comp.append((r, c))
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h_rows and 0 <= nc < h_cols:
                        if not visited[nr, nc] and grid[nr, nc] != 0:
                            visited[nr, nc] = True
                            q.append((nr, nc))
            components.append(comp)
    return components

ones_comps = find_nonzero_components(grid)
print(f"Found {len(ones_comps)} non-zero components")

output_grid = grid.copy()
total_filled = 0

for comp_idx, comp in enumerate(ones_comps):
    # Find the special value
    special_val = None
    for r, c in comp:
        if grid[r, c] > 1:
            special_val = grid[r, c]
            break

    if special_val:
        # Find which 1s are truly ENCLOSED - can't reach bg via orthogonal non-zero paths
        enclosed_ones = []

        for r, c in comp:
            if grid[r, c] == 1:
                # BFS through non-zeros to see if we hit background
                reachable_bg = False
                visited_check = set()
                q = deque([(r, c)])

                while q and not reachable_bg:
                    rr, cc = q.popleft()
                    if (rr, cc) in visited_check:
                        continue
                    visited_check.add((rr, cc))

                    # Check all 4 orthogonal directions
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = rr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if (nr, nc) not in visited_check:
                                if grid[nr, nc] == 0:
                                    reachable_bg = True
                                    break
                                elif grid[nr, nc] != 0:
                                    visited_check.add((nr, nc))
                                    q.append((nr, nc))

                # If NOT reachable to bg through non-zero cells, it's enclosed
                if not reachable_bg:
                    enclosed_ones.append((r, c))

        print(f"Comp {comp_idx}: special={special_val}, fillable_enclosed={len(enclosed_ones)}")

        for r, c in enclosed_ones:
            output_grid[r, c] = special_val

        total_filled += len(enclosed_ones)

print(f"\nTotal filled: {total_filled}")
submission = output_grid.tolist()

